     1	export interface Customer {
     2	  yearsWithMHPCO: number;
     3	}
     4	
     5	export interface Item {
     6	  type: string;
     7	  cursed?: boolean;
     8	  enchantment?: number;
     9	}
    10	
    11	const PROCESSING_FEE = 5;
    12	const FIRST_INSURANCE_SURCHARGE = 0.1;
    13	
    14	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
    15	  sword: 100,
    16	  amulet: 60,
    17	  staff: 80,
    18	  potion: 40,
    19	};
    20	
    21	// Components (e.g. runes, moonstones) are not individually price-listed: they all
    22	// share one tariff, so the component roster is the single source of which types
    23	// are components and what each of them costs.
    24	const COMPONENT_TYPES = ["rune", "moonstone"];
    25	const COMPONENT_BASE_PREMIUM = 25;
    26	
    27	const BASE_PREMIUMS: Record<string, number> = {
    28	  ...MAIN_ITEM_BASE_PREMIUMS,
    29	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_BASE_PREMIUM])),
    30	};
    31	
    32	const PREMIUM_PRECISION = 1e-9;
    33	
    34	function roundUpInMHPCOFavor(amount: number): number {
    35	  return Math.ceil(amount - PREMIUM_PRECISION);
    36	}
    37	
    38	const BLOCK_SIZE = 3;
    39	const BLOCK_BASE_PREMIUM = 60;
    40	
    41	// MHPCO reading of "alike": two items are alike exactly when their types match,
    42	// not merely when they belong to the same family (rune-y, gemstone-y).
    43	function countAlikeItems(items: Item[]): Map<string, number> {
    44	  const counts = new Map<string, number>();
    45	  for (const item of items) {
    46	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
    47	  }
    48	  return counts;
    49	}
    50	
    51	// A building block is offered for exactly 3 alike components.
    52	function blockOfferApplies(type: string, count: number): boolean {
    53	  return COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE;
    54	}
    55	
    56	function typeBasePremium(type: string, count: number): number {
    57	  if (blockOfferApplies(type, count)) {
    58	    return BLOCK_BASE_PREMIUM;
    59	  }
    60	  return count * BASE_PREMIUMS[type];
    61	}
    62	
    63	function policyBasePremium(items: Item[]): number {
    64	  let total = 0;
    65	  for (const [type, count] of countAlikeItems(items)) {
    66	    total += typeBasePremium(type, count);
    67	  }
    68	  return total;
    69	}
    70	
    71	const CURSE_SURCHARGE = 0.5;
    72	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
    73	const HIGH_ENCHANTMENT_LEVEL = 5;
    74	
    75	function isHighlyEnchanted(item: Item): boolean {
    76	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
    77	}
    78	
    79	// Each risk factor the MHPCO recognises contributes its own rate; a cursed and
    80	// highly enchanted item is assessed both surcharges.
    81	function riskSurchargeRate(item: Item): number {
    82	  return (
    83	    (item.cursed === true ? CURSE_SURCHARGE : 0) +
    84	    (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0)
    85	  );
    86	}
    87	
    88	// Item-scoped risk surcharges are assessed against the affected item's own base
    89	// premium, so each item is rated separately and the results are summed.
    90	function itemScopedSurcharges(items: Item[]): number {
    91	  return items.reduce(
    92	    (total, item) => total + BASE_PREMIUMS[item.type] * riskSurchargeRate(item),
    93	    0,
    94	  );
    95	}
    96	
    97	const LOYALTY_DISCOUNT = 0.2;
    98	const LOYALTY_YEARS = 2;
    99	
   100	function isLongStanding(customer: Customer): boolean {
   101	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
   102	}
   103	
   104	// A discount, so it enters the policy-scoped rate as a negative rate.
   105	function loyaltyRate(customer: Customer): number {
   106	  return isLongStanding(customer) ? -LOYALTY_DISCOUNT : 0;
   107	}
   108	
   109	// The MHPCO's policy-scoped tariff: each recognised policy-wide modifier contributes
   110	// its own rate, and the rates are assessed together against the policy base premium.
   111	function policyScopedRate(customer: Customer): number {
   112	  return FIRST_INSURANCE_SURCHARGE + loyaltyRate(customer);
   113	}
   114	
   115	// Policy-scoped modifiers are assessed against the policy base premium alone -- the
   116	// plain sum of the item base premiums, deliberately excluding item-scoped surcharges.
   117	function policyScopedModifiers(basePremium: number, customer: Customer): number {
   118	  return basePremium * policyScopedRate(customer);
   119	}
   120	
   121	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
   122	  const basePremium = policyBasePremium(items);
   123	  const modifiedPremium =
   124	    basePremium + itemScopedSurcharges(items) + policyScopedModifiers(basePremium, customer);
   125	  return roundUpInMHPCOFavor(modifiedPremium + PROCESSING_FEE);
   126	}
